    "body": "炎帝的小女儿女娃到东海游玩，不幸溺水而亡，魂灵化成一只花头白喙的小鸟，名叫精卫。她每天衔来西山的树枝和石子，投进东海，日复一日从不停止。大海嘲笑她，她答道：就算一千年一万年，也要把你填平。这份执着感动了后人。",
