    "body": "刘备白帝城托孤后，诸葛亮辅佐刘禅。公元二二七年，他决定北伐，临行前上《出师表》，劝刘禅亲贤臣、远小人，赏罚分明，并推荐郭攸之、费祎、董允、向宠等人。他说：臣鞠躬尽瘁，死而后已。全文情深意切，被誉为读《出师表》不流泪者不忠。",
